class Solution {
    private int gcd(int a,int b){
        while(b!=0){
            int temporary=a%b;
            a=b;
            b=temporary;
        }
        return a;
    }
    public List<Integer> replaceNonCoprimes(int[] nums){
        List<Integer> stack=new ArrayList<>();
        for(int value:nums){
            while(!stack.isEmpty()){
                int top=stack.get(stack.size()-1),divisor=gcd(top,value);
                if(divisor==1)break;
                stack.remove(stack.size()-1);
                value=(int)((long)top/divisor*value);
            }
            stack.add(value);
        }
        return stack;
    }
}

code.kotlin:
class Solution {
    private fun gcd(first:Int,second:Int):Int{
        var a=first;
        var b=second;
        while(b!=0){
            val temporary=a%b;
            a=b;
            b=temporary
        };
        return a
    };
    fun replaceNonCoprimes(nums:IntArray):List<Int>{
        val stack=mutableListOf<Int>();
        for(original in nums){
            var value=original;
            while(stack.isNotEmpty()){
                val top=stack.last();
                val divisor=gcd(top,value);
                if(divisor==1)break;
                stack.removeAt(stack.lastIndex);
                value=(top.toLong()/divisor*value).toInt()
            };
            stack.add(value)
        };
        return stack
    }
}

